"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, HTMLAttributes } from "react";

export type DotScanPattern = "rings" | "fibonacci" | "grid";

export interface DotScanProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** How the dots are laid out on the sphere. The band follows it: ring by ring, row by row, or a stripe winding down the spiral. */
  pattern?: DotScanPattern;
  /** Diameter of the front-most dots in px. Back dots shrink automatically. */
  dotSize?: number;
  /** Number of rows / dot density. Higher = more dots. */
  density?: number;
  /** Canvas size in px (the orb is square). */
  size?: number;
  /** Seconds for the band to read from the top pole to the bottom one. */
  duration?: number;
  /** Seconds the orb rests after the band leaves, before the next read. */
  gap?: number;
  /** Tilt toward the viewer in degrees, so the top of the orb shows. */
  tilt?: number;
  /** Dot color, any CSS color. */
  color?: string;
  /** Opacity of the dots furthest away (0–1). Front dots are always 1. */
  backOpacity?: number;
  /** Coast to a stop on the current frame. Turning it back off eases the animation back up to speed. */
  paused?: boolean;
  /** Accessible name; the wrapper is role="status". */
  label?: string;
}

type Settings = GlobeSettings & Required<Pick<DotScanProps, "duration" | "gap">>;

/** Every number the drawing reads, as the latest props want it. */
function targetsOf(s: Settings) {
  return { ...globeTargets(s), ...scanMotion.targets(s) };
}

export function DotScan({
  pattern = "rings",
  dotSize = 3,
  density = 12,
  size = 160,
  duration = 2,
  gap = 0.4,
  tilt = 18,
  color = "#e4e4e7",
  backOpacity = 0.2,
  paused = false,
  label = "Reading",
  ...rest
}: DotScanProps) {
  const settings: Settings = { pattern, dotSize, density, size, duration, gap, tilt, color, backOpacity, paused };
  return <LoaderCanvas settings={settings} targets={targetsOf} shape={globeShape} settle={globeSettle} scene={scanMotion.scene} label={label} {...rest} />;
}

export default DotScan;

/**
 * Glide times are a spring's time constant, not a duration: a glide is about 90% of the way to its target
 * after twice its time, so `SETTLE` reads as a ~240ms change.
 */

/** Seconds (roughly) a changed prop takes to glide to its new value: size, spacing, timing and the like. */
const SETTLE = 0.12;

/** Color and opacity: faster, since nothing moves (~150ms). */
const FADE_SETTLE = 0.075;

/** Changing animation: one motion blending into the next (~300ms). */
const BLEND_SETTLE = 0.15;

/** Pausing: seconds (roughly) the animation takes to coast to a stop (~300ms). */
const STOP_SETTLE = 0.15;

/** Resuming: seconds (roughly) the animation takes to get back up to speed (~400ms). */
const START_SETTLE = 0.2;

/** A value that glides toward its target on a critically damped spring: no jump, no overshoot. */
type Glide = { value: number; velocity: number; target: number };

function glide(value: number): Glide {
  return { value, velocity: 0, target: value };
}

function snap(g: Glide) {
  g.value = g.target;
  g.velocity = 0;
}

/** Moves `g` toward its target. Returns false once it has arrived and is at rest. */
function stepGlide(g: Glide, dt: number, time: number) {
  if (g.value === g.target && g.velocity === 0) return false;
  const omega = 2 / time;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const change = g.value - g.target;
  const temp = (g.velocity + omega * change) * dt;
  g.velocity = (g.velocity - omega * temp) * decay;
  g.value = g.target + (change + temp) * decay;
  if (Math.abs(g.value - g.target) < 1e-3 && Math.abs(g.velocity) < 1e-3) snap(g);
  return true;
}

/** The glided value of every target, plus the canvas `size` and the pause `rate` (0 paused, 1 running). */
type Values<K extends string> = Record<K | "size" | "rate", number>;

/** What a scene sees each frame. `layers` holds every shape on screen; more than one while a change cross-fades. */
interface Frame<S, K extends string, L> {
  settings: S;
  v: Values<K>;
  layers: { shape: L; fade: number }[];
  size: number;
  /** The viewer asked for reduced motion: the clock holds still, so a scene that ends somewhere should jump there. */
  reduced: boolean;
}

interface Scene<S, K extends string, L> {
  /** Moves the scene's own clock on by `dt` seconds. Scale by `v.rate` so pausing coasts to a stop. */
  advance?(dt: number, frame: Frame<S, K, L>): void;
  /** Paints one frame onto a cleared canvas, already scaled to `size` px. */
  draw(ctx: CanvasRenderingContext2D, frame: Frame<S, K, L>): void;
}

interface LoaderCanvasProps<S extends { size: number; paused: boolean }, K extends string, L>
  extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** The latest props. Read by `targets` and `shape` on every render, and by the scene every frame. */
  settings: S;
  /** Every number the scene reads, as the latest settings want it. Each glides to its new value. */
  targets: (s: NoInfer<S>) => Record<K, number>;
  /**
   * Geometry rebuilt when its key changes. The old shape's fade glides to 0 while the new one's glides to 1:
   * a plain cross-fade, unless `morph` links the two so the scene can move one into the other.
   */
  shape?: {
    key: (s: NoInfer<S>) => string;
    build: (s: NoInfer<S>) => L;
    /** Called when `to` replaces `from`, whose fade is `fade` at that moment. */
    morph?: (from: L, to: L, fade: number) => void;
    /** Seconds (roughly) a shape change takes. Defaults to `BLEND_SETTLE`. */
    settle?: number;
  };
  /** Seconds (roughly) each target takes to glide to a new value, by key. Unlisted keys take `SETTLE`. */
  settle?: Partial<Record<NoInfer<K> | "size", number>>;
  /** Seconds (roughly) pausing takes to coast to a stop, and resuming to get back up to speed. */
  pause?: { stop: number; start: number };
  /** Called once on mount; the returned scene keeps its own clock between frames. */
  scene: () => Scene<NoInfer<S>, K, L>;
  label: string;
}

/**
 * A square canvas that runs a scene: props glide instead of jumping, pausing coasts, shape changes
 * cross-fade or morph, reduced motion holds still, and the loop sleeps once nothing is moving.
 */
function LoaderCanvas<S extends { size: number; paused: boolean }, K extends string, L>({
  settings,
  targets,
  shape,
  settle,
  pause,
  scene,
  label,
  className,
  style,
  ...rest
}: LoaderCanvasProps<S, K, L>) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Only the first size reaches the DOM through React; after that the loop glides it.
  const [initialSize] = useState(settings.size);
  const latest = useRef({ settings, targets, shape, settle, pause, scene });
  const wakeRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    latest.current = { settings, targets, shape, settle, pause, scene };
    wakeRef.current?.();
  });

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const { settings: first, shape: shapeOf, scene: makeScene } = latest.current;
    const sceneNow = makeScene();
    const glides = {} as Record<string, Glide>;
    const v = {} as Values<K>;
    let shapes = shapeOf ? [{ key: shapeOf.key(first), shape: shapeOf.build(first), fade: glide(1) }] : [];
    const frameInfo: Frame<S, K, L> = { settings: first, v, layers: [], size: 1, reduced: reduceMotion.matches };
    let shownSize = -1;
    let frame = 0;
    let last = 0;
    // Off screen or in a hidden tab, the loop sleeps; it picks up where it left off once seen again.
    let onScreen = true;
    const visible = () => onScreen && document.visibilityState === "visible";

    const targetsNow = () => {
      const { settings: s, targets } = latest.current;
      return { ...targets(s), size: s.size, rate: s.paused ? 0 : 1 } as Record<string, number>;
    };
    for (const [k, value] of Object.entries(targetsNow())) glides[k] = glide(value);

    /** Refreshes what the scene reads from the glides and shapes. */
    const read = () => {
      for (const k in glides) (v as Record<string, number>)[k] = glides[k].value;
      frameInfo.settings = latest.current.settings;
      frameInfo.layers = shapes.map(({ shape, fade }) => ({ shape, fade: fade.value }));
      frameInfo.size = Math.max(1, v.size);
      frameInfo.reduced = reduceMotion.matches;
    };

    const sync = () => {
      const { settings: s, shape: shapeOf } = latest.current;
      for (const [k, value] of Object.entries(targetsNow())) glides[k].target = value;
      if (shapeOf) {
        const key = shapeOf.key(s);
        if (key !== shapes[shapes.length - 1].key) {
          for (const shape of shapes) shape.fade.target = 0;
          const fade = glide(0);
          fade.target = 1;
          const prev = shapes[shapes.length - 1];
          const next = { key, shape: shapeOf.build(s), fade };
          shapeOf.morph?.(prev.shape, next.shape, prev.fade.value);
          shapes.push(next);
        }
      }
      // Reduced motion: hold still and apply changes at once.
      if (reduceMotion.matches) {
        glides.rate.target = 0;
        for (const g of Object.values(glides)) snap(g);
        for (const shape of shapes) snap(shape.fade);
      }
    };

    const draw = () => {
      read();
      const size = frameInfo.size;
      if (size !== shownSize) {
        shownSize = size;
        wrapper.style.width = wrapper.style.height = `${size}px`;
        canvas.style.width = canvas.style.height = `${size}px`;
        const px = Math.round(size * dpr);
        if (canvas.width !== px) canvas.width = canvas.height = px;
      }
      ctx.setTransform(canvas.width / size, 0, 0, canvas.width / size, 0, 0);
      ctx.clearRect(0, 0, size, size);
      sceneNow.draw(ctx, frameInfo);
      ctx.globalAlpha = 1;
    };

    const tick = (now: number) => {
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      let moving = false;
      const times: Partial<Record<string, number>> = latest.current.settle ?? {};
      const pauseTimes = latest.current.pause;
      for (const [k, g] of Object.entries(glides)) {
        // Stopping and starting take their own times; every other target its own, else `SETTLE`.
        const time =
          k === "rate"
            ? g.target > 0
              ? (pauseTimes?.start ?? START_SETTLE)
              : (pauseTimes?.stop ?? STOP_SETTLE)
            : (times[k] ?? SETTLE);
        if (stepGlide(g, dt, time)) moving = true;
      }
      const shapeSettle = latest.current.shape?.settle ?? BLEND_SETTLE;
      for (const shape of shapes) if (stepGlide(shape.fade, dt, shapeSettle)) moving = true;
      shapes = shapes.filter((shape) => shape.fade.target > 0 || shape.fade.value > 0);

      if (sceneNow.advance) {
        read();
        sceneNow.advance(dt, frameInfo);
      }
      draw();
      // Sleep once everything has settled and the animation is paused, or nobody can see it.
      frame = visible() && (moving || glides.rate.value > 0) ? requestAnimationFrame(tick) : 0;
    };

    const wake = () => {
      sync();
      if (frame || !visible()) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    const sleepOrWake = () => {
      if (visible()) wake();
      else {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    };
    const observer = new IntersectionObserver(
      (entries) => {
        onScreen = entries[entries.length - 1].isIntersecting;
        sleepOrWake();
      },
      { rootMargin: "64px" },
    );
    observer.observe(wrapper);

    wakeRef.current = wake;
    reduceMotion.addEventListener("change", wake);
    document.addEventListener("visibilitychange", sleepOrWake);
    sync();
    draw();
    wake();
    return () => {
      cancelAnimationFrame(frame);
      wakeRef.current = null;
      observer.disconnect();
      reduceMotion.removeEventListener("change", wake);
      document.removeEventListener("visibilitychange", sleepOrWake);
    };
  }, []);

  const wrapperStyle: CSSProperties = { width: initialSize, height: initialSize, ...style };

  return (
    <div ref={wrapperRef} role="status" aria-label={label} className={className} style={wrapperStyle} {...rest}>
      <canvas ref={canvasRef} style={{ width: initialSize, height: initialSize, display: "block" }} />
    </div>
  );
}

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to sRGB [r, g, b, a] by painting it into one pixel, so it can be blended. */
function parseColor(color: string): [number, number, number, number] {
  probe ??= document.createElement("canvas").getContext("2d", { willReadFrequently: true });
  if (!probe) return [228, 228, 231, 1];
  probe.clearRect(0, 0, 1, 1);
  probe.fillStyle = "#000"; // An invalid color leaves fillStyle as it was, so start from a known one.
  probe.fillStyle = color;
  probe.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = probe.getImageData(0, 0, 1, 1).data;
  return [r, g, b, a / 255];
}

/** A CSS color as glide targets, so a color change blends instead of jumping. */
function colorTargets(color: string) {
  const [red, green, blue, alpha] = parseColor(color);
  return { red, green, blue, alpha };
}

/** The blended color as an opaque CSS color; its alpha is applied per dot through globalAlpha. */
function rgb(v: { red: number; green: number; blue: number }) {
  return `rgb(${v.red} ${v.green} ${v.blue})`;
}

/** How the dots are laid out on the sphere. */
type GlobePattern = "rings" | "fibonacci" | "grid";

/** Props every dot sphere takes. */
interface GlobeSettings {
  pattern: GlobePattern;
  dotSize: number;
  density: number;
  size: number;
  tilt: number;
  color: string;
  backOpacity: number;
  paused: boolean;
}

/**
 * A point on the unit sphere. `row` is its latitude row from the top (0 to `rows`); `step` is its
 * place in the pattern's own order, which on the spiral winds down the arms instead of the rows.
 */
type GlobePoint = { x: number; y: number; z: number; row: number; step: number };

/** Where `place` puts a point before the tilt, plus how much it shrinks (`size`) and dims (`dim`). */
type Placed = { x: number; y: number; z: number; size: number; dim: number };

/** Back dots are drawn at this fraction of `dotSize`. */
const BACK_SCALE = 0.35;

/** Rows the spiral stripe drops over one full turn around the orb, as a fraction of all rows. */
const SPIRAL_PITCH = 0.5;

function rowsOf(s: GlobeSettings) {
  return Math.max(3, Math.round(s.density));
}

function buildPoints(pattern: GlobePattern, rows: number) {
  const points: GlobePoint[] = [];

  if (pattern === "fibonacci") {
    // The spiral has no rows, so band dots by height into rows, and let the step follow its arms:
    // mixing height with how far around the orb a dot sits turns a wave into a diagonal stripe
    // winding down the sphere. The stripe's seam (where "around" wraps) sits at the back, where the dots are faintest.
    const count = Math.round(rows * rows * 1.25);
    const golden = Math.PI * (3 - Math.sqrt(5));
    const pitch = rows * SPIRAL_PITCH;
    for (let i = 0; i < count; i++) {
      const y = 1 - ((i + 0.5) / count) * 2;
      const r = Math.sqrt(1 - y * y);
      const a = i * golden;
      const x = Math.cos(a) * r;
      const z = Math.sin(a) * r;
      const around = Math.atan2(-x, z) / (Math.PI * 2) + 0.5;
      points.push({ x, y, z, row: Math.round(((1 - y) / 2) * rows), step: ((1 - y) / 2) * rows + around * pitch });
    }
    return { points, steps: rows + pitch };
  }

  // Rings and grid share latitude rows; each row moves as one, so its step is its row number.
  // Poles get a single dot each.
  points.push({ x: 0, y: 1, z: 0, row: 0, step: 0 }, { x: 0, y: -1, z: 0, row: rows, step: rows });
  const cols = rows * 2;
  for (let i = 1; i < rows; i++) {
    const lat = Math.PI / 2 - (i / rows) * Math.PI;
    const y = Math.sin(lat);
    const r = Math.cos(lat);
    // Rings keep even spacing along each row; grid keeps meridians aligned.
    const n = pattern === "grid" ? cols : Math.max(1, Math.round(cols * r));
    const offset = pattern === "grid" ? 0 : (i % 2) * (Math.PI / n);
    for (let j = 0; j < n; j++) {
      const a = (j / n) * Math.PI * 2 + offset;
      points.push({ x: Math.cos(a) * r, y, z: Math.sin(a) * r, row: i, step: i });
    }
  }
  return { points, steps: rows };
}

/** The sphere's points, plus scratch space for projecting and depth-sorting them each frame. */
interface GlobeShape {
  pattern: GlobePattern;
  points: GlobePoint[];
  rows: number;
  /** The last step on the orb, so a sweep from step 0 to `steps` crosses all of it. */
  steps: number;
  placed: Placed[];
  order: number[];
  // Each row's own spin angle, for animations that turn rows separately. Accumulated so
  // timing changes mid-turn bend the motion instead of jumping it.
  rowAngles: Float64Array;
  rowSin: Float64Array;
  rowCos: Float64Array;
  /** This orb's fade as of the last frame: 0 to 1 while it morphs in, 1 to 0 while it morphs out. */
  fade: number;
  /** Set while this orb morphs in: each point sets off from `from`'s point `source[i]`. */
  arrival: { from: GlobeShape; source: Int32Array; frozen: number | null } | null;
  /**
   * Set while this orb morphs out. Points some new point set off from (`kept`) hand over to it at once;
   * the rest travel into `to`'s point `target[i]` and fade on the way.
   */
  leaving: { to: GlobeShape; target: Int32Array; kept: Uint8Array; start: number } | null;
}

function buildGlobe(s: GlobeSettings): GlobeShape {
  const rows = rowsOf(s);
  const { points, steps } = buildPoints(s.pattern, rows);
  return {
    pattern: s.pattern,
    points,
    rows,
    steps,
    placed: points.map((): Placed => ({ x: 0, y: 0, z: 0, size: 1, dim: 1 })),
    order: points.map((_, i) => i),
    rowAngles: new Float64Array(rows + 1),
    rowSin: new Float64Array(rows + 1),
    rowCos: new Float64Array(rows + 1).fill(1),
    fade: 1,
    arrival: null,
    leaving: null,
  };
}

/** For each point in `to`, the closest point in `from` on the sphere. */
function nearest(from: GlobePoint[], to: GlobePoint[]) {
  const out = new Int32Array(to.length);
  for (let i = 0; i < to.length; i++) {
    const p = to[i];
    let best = -Infinity;
    for (let j = 0; j < from.length; j++) {
      const q = from[j];
      const dot = p.x * q.x + p.y * q.y + p.z * q.z;
      if (dot > best) {
        best = dot;
        out[i] = j;
      }
    }
  }
  return out;
}

/**
 * Links an orb to the one replacing it, so the same dots travel into the new layout instead of
 * the two cross-fading. Every new dot sets off from its closest old dot; old dots no new one picked
 * glide into their closest new dot and fade out there.
 */
function morphGlobe(from: GlobeShape, to: GlobeShape, fade: number) {
  // A change mid-morph: hold the old orb where it got to, and set off from there.
  if (from.arrival) {
    if (fade < 1) from.arrival.frozen = fade;
    else from.arrival = null;
  }
  const source = nearest(from.points, to.points);
  const kept = new Uint8Array(from.points.length);
  for (const j of source) kept[j] = 1;
  to.arrival = { from, source, frozen: null };
  from.leaving = { to, target: nearest(to.points, from.points), kept, start: Math.max(1e-3, fade) };
}

/** Identifies an orb's geometry; a pattern or density change morphs the old orb's dots into the new one. */
function globeKey(s: GlobeSettings) {
  return `${s.pattern}:${rowsOf(s)}`;
}

/**
 * Dots only travel to their nearest spot in the new layout, a short way, so a pattern or density change
 * takes the same ~300ms as switching animation: every structural change in the row blends at one pace.
 */
const globeShape = { key: globeKey, build: buildGlobe, morph: morphGlobe, settle: BLEND_SETTLE };

/** The globe's own glide targets; spread these into a component's targets. */
function globeTargets(s: GlobeSettings) {
  return { ...colorTargets(s.color), dotSize: s.dotSize, tilt: s.tilt, backOpacity: s.backOpacity };
}

type GlobeKey = keyof ReturnType<typeof globeTargets>;

function lerpPlaced(a: Placed, b: Placed, t: number) {
  b.x = a.x + (b.x - a.x) * t;
  b.y = a.y + (b.y - a.y) * t;
  b.z = a.z + (b.z - a.z) * t;
  b.size = a.size + (b.size - a.size) * t;
  b.dim = a.dim + (b.dim - a.dim) * t;
}

/**
 * Places, tilts, depth-sorts and paints every orb on screen. `placeFor` is called once per orb and
 * returns how to place each of its points; far dots shrink and fade, so only placement varies.
 * While a pattern changes, dots are placed partway between the old orb's motion and the new one's.
 */
function drawGlobe<S, K extends string, L extends GlobeShape>(
  ctx: CanvasRenderingContext2D,
  { v, layers, size }: Frame<S, K | GlobeKey, L>,
  radius: number,
  placeFor: (shape: L) => (point: GlobePoint, out: Placed) => void,
) {
  const dotSize = Math.max(0, v.dotSize);
  const backOpacity = v.backOpacity;
  const center = size / 2;
  const tiltRad = (v.tilt * Math.PI) / 180;
  const sinT = Math.sin(tiltRad);
  const cosT = Math.cos(tiltRad);

  const placers = new Map<L, (point: GlobePoint, out: Placed) => void>();
  const placerOf = (shape: L) => {
    let place = placers.get(shape);
    if (!place) placers.set(shape, (place = placeFor(shape)));
    return place;
  };
  const scratch: Placed[] = [];
  const toward: Placed = { x: 0, y: 0, z: 0, size: 1, dim: 1 };

  /** Where point `i` shows: its own motion, or partway there from the orb it is morphing in from. */
  const placeAt = (shape: L, i: number, out: Placed, depth = 0) => {
    out.size = out.dim = 1;
    placerOf(shape)(shape.points[i], out);
    const arrival = shape.arrival;
    if (!arrival) return;
    const t = arrival.frozen ?? shape.fade;
    if (t >= 1) return;
    const start = (scratch[depth] ??= { x: 0, y: 0, z: 0, size: 1, dim: 1 });
    placeAt(arrival.from as L, arrival.source[i], start, depth + 1);
    lerpPlaced(start, out, t);
  };

  for (const layer of layers) {
    const { shape } = layer;
    shape.fade = layer.fade;
    // Arrived: let go of the old orb.
    if (shape.arrival && !shape.leaving && shape.fade >= 1) shape.arrival = null;
  }

  ctx.fillStyle = rgb(v);
  for (const { shape, fade } of layers) {
    const { points, placed, order, leaving } = shape;
    // 1 while a leaving orb's unpicked dots are still fully on, down to 0 as they arrive.
    const keep = leaving ? Math.min(1, Math.max(0, fade / leaving.start)) : 1;
    for (let i = 0; i < points.length; i++) {
      const p = placed[i];
      placeAt(shape, i, p);
      if (leaving) {
        if (leaving.kept[i]) p.dim = 0;
        else {
          placeAt(leaving.to as L, leaving.target[i], toward);
          lerpPlaced(p, toward, 1 - keep);
          Object.assign(p, toward);
          p.dim *= keep;
        }
      }
      // Tilt toward the viewer, so the top of the orb shows.
      const { y, z } = p;
      p.y = y * cosT - z * sinT;
      p.z = y * sinT + z * cosT;
    }
    order.sort((i, j) => placed[i].z - placed[j].z);

    const alpha = v.alpha;
    for (const i of order) {
      const p = placed[i];
      if (p.dim <= 0) continue;
      const depth = Math.min(1, Math.max(0, (p.z + 1) / 2)); // 0 = back, 1 = front
      const r = (dotSize / 2) * (BACK_SCALE + (1 - BACK_SCALE) * depth) * p.size;
      ctx.globalAlpha = alpha * (backOpacity + (1 - backOpacity) * depth) * p.dim;
      ctx.beginPath();
      ctx.arc(center + p.x * radius, center - p.y * radius, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

/**
 * Every way a dot sphere can move. Each motion turns its props into glide targets and runs a scene
 * over the shared globe geometry, so single loaders and the switchable DotGlobe draw the same thing.
 */

type GlobeFrame<K extends string> = Frame<unknown, K | GlobeKey, GlobeShape>;

/**
 * The orb's radius, the same for every motion. Where lift is in play (DotLift, or DotGlobe whatever
 * animation it runs), it leaves room for a ring at the peak of its push, so switching animation never resizes the orb.
 */
function radiusOf({ v, size }: GlobeFrame<never>) {
  const lift = Math.max(0, (v as Partial<Record<"lift", number>>).lift ?? 0);
  return (size / 2 - Math.max(0, v.dotSize)) / (1 + lift);
}

/**
 * Seconds (roughly) each target glides for when its prop changes, shared by DotGlobe and every single
 * sphere; unlisted keys (size, dot size, tilt, lift, depth, width, timing) take `SETTLE`. Color and opacity
 * fade faster, since nothing moves. Direction flips and animation switches blend one motion into the next.
 */
const globeSettle = {
  red: FADE_SETTLE,
  green: FADE_SETTLE,
  blue: FADE_SETTLE,
  alpha: FADE_SETTLE,
  backOpacity: FADE_SETTLE,
  dir: BLEND_SETTLE,
  from: BLEND_SETTLE,
  mix_spin: BLEND_SETTLE,
  mix_cascade: BLEND_SETTLE,
  mix_lift: BLEND_SETTLE,
  mix_tide: BLEND_SETTLE,
  mix_twist: BLEND_SETTLE,
  mix_scan: BLEND_SETTLE,
  mix_rise: BLEND_SETTLE,
  mix_sweep: BLEND_SETTLE,
  mix_compact: BLEND_SETTLE,
  mix_swarm: BLEND_SETTLE,
  down: BLEND_SETTLE,
};

/** A loop of one move (`at` runs 0 to 1), then a rest (`rested` seconds), over and over. */
type MoveLoop = { at: number; rested: number };

/**
 * Runs `seconds` through a move-then-rest loop. Progress is kept rather than worked out from a cycle,
 * so changing the timing only changes the speed: a longer gap never jumps a move under way.
 * `moved` hears each stretch of progress, so a spin can add the turns up.
 */
function runMoveLoop(loop: MoveLoop, seconds: number, length: number, gap: number, moved?: (from: number, to: number) => void) {
  // A frame can hold several short moves (a zero gap takes none at all); cap it so nothing spins.
  for (let guard = 0; guard < 16 && seconds > 0; guard++) {
    if (loop.at < 1) {
      const from = loop.at;
      const need = (1 - from) * length;
      loop.at = seconds < need ? from + seconds / length : 1;
      seconds -= Math.min(seconds, need);
      moved?.(from, loop.at);
    } else {
      const need = Math.max(0, gap - loop.rested);
      if (seconds < need) {
        loop.rested += seconds;
        seconds = 0;
      } else {
        seconds -= need;
        loop.at = loop.rested = 0;
      }
    }
  }
}

/** 1 at a wave's middle `mid`, easing to 0 `half` steps either side: how much of the wave step `d` is in. */
function waveAt(d: number, mid: number, half: number) {
  const dist = Math.abs(d - mid) / half;
  return dist < 1 ? Math.cos((Math.PI / 2) * dist) ** 2 : 0;
}

/** Rows the scan band lights at once: a line or two, like the line being read. */
const SCAN_WIDTH = 1.75;

/** Opacity of the dots the scan isn't on, so the lit band stands out like the line being read. */
const SCAN_REST_OPACITY = 0.5;

/** How much bigger a dot draws at the middle of the scan band. */
const SCAN_SWELL = 0.35;

interface ScanSettings {
  duration: number;
  gap: number;
}

/** A thin band of light reads down the orb at a steady pace, brightening and swelling the dots it is on. */
const scanMotion = {
  targets(s: ScanSettings) {
    return { duration: s.duration, gap: s.gap };
  },
  scene(): Scene<unknown, "duration" | "gap" | GlobeKey, GlobeShape> {
    // One read down the orb, then a rest for `gap`; kept as progress, like the tide, so a duration change only changes the pace.
    const loop: MoveLoop = { at: 0, rested: 0 };

    return {
      advance(dt, { v }) {
        runMoveLoop(loop, dt * v.rate, Math.max(0.05, v.duration), Math.max(0, v.gap));
      },
      draw(ctx, frame) {
        const half = SCAN_WIDTH / 2;
        // Linear: a read moves at a constant pace. It holds at 1 through the gap, past the bottom pole.
        const travel = loop.at;
        drawGlobe(ctx, frame, radiusOf(frame), ({ steps }) => {
          const mid = -half + travel * (steps + half * 2);
          return ({ x, y, z, step }, out) => {
            const w = waveAt(step, mid, half);
            // Nothing moves: the band only lights and swells the dots it passes.
            out.x = x;
            out.y = y;
            out.z = z;
            out.size = 1 + SCAN_SWELL * w;
            out.dim = SCAN_REST_OPACITY + (1 - SCAN_REST_OPACITY) * w;
          };
        });
      },
    };
  },
};
